SELECT id, session_id, event_type, page, AVG(duration_sec) OVER w_part AS duration_sec_avg_2, STDDEV_SAMP(duration_sec) OVER (PARTITION BY session_id) AS session_id_stddev_samp_duration_sec, AVG(duration_sec) OVER w_part AS duration_sec_avg_2_2 FROM web_events WHERE session_id IN (9, 22, 23) WINDOW w_part AS (PARTITION BY session_id ORDER BY duration_sec, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW);
